"""matplotlib.sphinxext.plot_directive — Sphinx ``.. plot::`` directive stub."""


PLOT_FORMATS = [('png', 100), ('hires.png', 200), ('pdf', 50)]


def setup(app=None):
    """Sphinx-extension entry point. The shim doesn't run Sphinx so
    this is a no-op that returns the expected ``{'version': ...}``
    dictionary."""
    return {'version': '0.0-shim', 'parallel_read_safe': True,
            'parallel_write_safe': True}


def plot_directive(*args, **kwargs):
    """The directive function itself — Sphinx parses arguments through
    this. Returns an empty list (no docutils nodes)."""
    return []


class PlotDirective:
    """Class-based form of the directive used by newer Sphinx releases."""
    has_content = True
    required_arguments = 0
    optional_arguments = 2
    final_argument_whitespace = False
    option_spec = {}

    def run(self):
        return []


def plot_context():
    """Return the default context dict that ``.. plot::`` exposes to
    embedded code blocks (numpy + matplotlib.pyplot)."""
    import numpy as np
    from matplotlib import pyplot as plt
    return {'np': np, 'plt': plt}


def render_figures(code, code_path, output_dir, output_base, context,
                    function_name=None, config=None, context_reset=False,
                    close_figs=False, code_includes=None):
    """Execute a ``.. plot::`` code block and save the resulting
    figures to ``output_dir``. Returns a list of ``ImageFile`` entries
    describing each saved figure.

    The shim runs the code in an exec() against the standard
    ``plot_context`` (numpy + pyplot) and walks `Gcf` for any
    resulting figures.
    """
    import os
    from matplotlib import pyplot as plt
    from matplotlib._pylab_helpers import Gcf

    if context_reset:
        try: plt.close('all')
        except Exception: pass

    ctx = plot_context()
    if context: ctx.update(context)

    # Make sure the output directory exists.
    try: os.makedirs(output_dir, exist_ok=True)
    except OSError: pass

    # Run the user code.
    try:
        exec(remove_coding(code), ctx)
    except Exception as e:
        # Re-raise as PlotError so callers see a directive-specific exception.
        raise PlotError(str(e)) from e

    # Collect every figure that exec produced.
    results = []
    fig_managers = list(Gcf.get_all_fig_managers())
    formats = list(get_plot_formats(config) if config else PLOT_FORMATS)
    for i, mgr in enumerate(fig_managers):
        fig = getattr(mgr, 'canvas', None)
        if fig is None:
            continue
        img = ImageFile(basename=f'{output_base}_{i:02d}', dirname=output_dir)
        for fmt, dpi in formats:
            path = os.path.join(output_dir, f'{img.basename}.{fmt}')
            try:
                if hasattr(mgr, 'figure'):
                    mgr.figure.savefig(path, dpi=dpi)
                elif hasattr(fig, 'savefig'):
                    fig.savefig(path, dpi=dpi)
                img.formats.append(fmt)
            except Exception:
                pass
        results.append(img)
    if close_figs:
        try: plt.close('all')
        except Exception: pass
    return results


def out_of_date(original, derived):
    """Whether ``derived`` is older than ``original`` — used for
    incremental rebuilds. Always returns True so callers regenerate."""
    return True


def remove_coding(text):
    """Strip a Python-2-style coding declaration from a source string."""
    return '\n'.join(line for line in text.split('\n')
                     if not line.startswith('# -*- coding'))


def split_code_at_show(text):
    """Split a code block on ``plt.show()`` calls — used to separate
    individual figures in a single directive."""
    parts = []
    cur = []
    for line in text.split('\n'):
        cur.append(line)
        if 'plt.show()' in line:
            parts.append('\n'.join(cur)); cur = []
    if cur:
        parts.append('\n'.join(cur))
    return parts


def jinja2_template_context():
    return {}


def doctest_directive(*args, **kwargs):
    return []


