# Jinja-style HTML template for embedding plots.
TEMPLATE = '{{ figure }}'
TEMPLATE_SRCSET = '{{ srcset }}'


class PlotError(RuntimeError):
    """Raised when ``.. plot::`` fails to render."""
    pass


class ImageFile:
    """Container for a single rendered plot image — path + formats."""
    def __init__(self, basename='', dirname=''):
        self.basename = basename
        self.dirname = dirname
        self.formats = []


def clear_state(plot_rcparams=None, close=True):
    """Reset rcParams + close all open figures before rendering."""
    if close:
        from matplotlib import pyplot as plt
        plt.close('all')


def contains_doctest(text):
    """True if ``text`` looks like a doctest block (starts with ``>>>``)."""
    return any(line.strip().startswith('>>>') for line in text.split('\n'))


def get_plot_formats(config):
    """Return the configured plot formats — defaults to png/hires/pdf."""
    return list(PLOT_FORMATS)


def mark_plot_labels(app, document):
    """Walk a docutils document and tag plot labels for cross-reference."""
    pass


def run(arguments, content, options, state_machine, state, lineno):
    """Implementation of the directive — returns no docutils nodes."""
    return []


def exception_template(*args, **kwargs):
    """Format an exception traceback for inclusion in the error block."""
    return ''
